def agent_action(sandbox, agent_body, step_count):
    seat = sandbox.get_swing_seat()
    if seat is None:
        return
    pos = seat.position
    vel = seat.linearVelocity
    target_y = 11.7
    target_x_min = 9.35
    target_x_max = 10.65

    fx = 0.0
    fy = 0.0

    if pos.y < target_y:
        # Add energy by applying vertical force in the direction of velocity
        if vel.y > 0:
            fy = 42.0  # Upward force to add energy during upward motion
        elif vel.y < 0:
            fy = -42.0  # Downward force to add energy during downward motion
    else:
        # Adjust x position to align with target zone
        if pos.x < target_x_min:
            # Apply downward force to create clockwise torque (pull x right)
            fy = -42.0
        elif pos.x > target_x_max:
            # Apply upward force to create counterclockwise torque (pull x left)
            fy = 42.0
        else:
            fy = 0.0  # No force needed if already in target x range

    # Apply the calculated vertical force
    sandbox.apply_force_to_seat(fx, fy)
